// LocalServiceHandler is an implementation of the hermesh.local.v1.LocalService service.
type LocalServiceHandler interface {
	GetStatus(context.Context, *v1.GetStatusRequest) (*v1.GetStatusResponse, error)
	// Onboarding: the first trusted device creates the owner.
	Setup(context.Context, *v1.SetupRequest) (*v1.SetupResponse, error)
	// Another device joins the owner (docs/trusted-devices.md 4.2): it asks,
	// waits for a trusted device to approve, then the person confirms they
	// approved it there, and only then is the owner kept.
	RequestJoin(context.Context, *v1.RequestJoinRequest) (*v1.RequestJoinResponse, error)
	// Long poll: returns when approved or expired, or after about 25s.
	WaitJoin(context.Context, *v1.WaitJoinRequest) (*v1.WaitJoinResponse, error)
	ConfirmJoin(context.Context, *v1.ConfirmJoinRequest) (*v1.ConfirmJoinResponse, error)
	// Trusted devices.
	ListDevices(context.Context, *v1.ListDevicesRequest) (*v1.ListDevicesResponse, error)
	// Approves a device's join request: signs the next root cert with it.
	ApproveDevicePairing(context.Context, *v1.ApproveDevicePairingRequest) (*v1.ApproveDevicePairingResponse, error)
	// Removes another device: the next root cert without it, what it signed
	// re-issued by this one, and its own machine revoked.
	RemoveDevice(context.Context, *v1.RemoveDeviceRequest) (*v1.RemoveDeviceResponse, error)
	// Forgets the owner on this device, after it was removed, so it can be
	// set up again or join again. Its own machine keeps its projects.
	Leave(context.Context, *v1.LeaveRequest) (*v1.LeaveResponse, error)
	// Signing delegation.
	WatchSigningRequests(context.Context, *v1.WatchSigningRequestsRequest, *connect.ServerStream[v1.SigningRequest]) error
	CompleteSigningRequest(context.Context, *v1.CompleteSigningRequestRequest) (*v1.CompleteSigningRequestResponse, error)
	// This Mac as an execution machine.
	SetLocalMachine(context.Context, *v1.SetLocalMachineRequest) (*v1.SetLocalMachineResponse, error)
	// Pairing.
	LookupPairing(context.Context, *v1.LookupPairingRequest) (*v1.LookupPairingResponse, error)
	// Requests waiting for this owner's approval, newest first: machines and
	// personal agents that used the connection address.
	ListPairingRequests(context.Context, *v1.ListPairingRequestsRequest) (*v1.ListPairingRequestsResponse, error)
	ApproveMachinePairing(context.Context, *v1.ApproveMachinePairingRequest) (*v1.ApproveMachinePairingResponse, error)
	ApproveClientPairing(context.Context, *v1.ApproveClientPairingRequest) (*v1.ApproveClientPairingResponse, error)
	// Machines.
	ListMachines(context.Context, *v1.ListMachinesRequest) (*v1.ListMachinesResponse, error)
	RenameMachine(context.Context, *v1.RenameMachineRequest) (*v1.RenameMachineResponse, error)
	SetMachinePaused(context.Context, *v1.SetMachinePausedRequest) (*v1.SetMachinePausedResponse, error)
	RemoveMachine(context.Context, *v1.RemoveMachineRequest) (*v1.RemoveMachineResponse, error)
	// Checks this Mac's coding agents again (installed, version, signed in),
	// in the background: they are only checked when something needs them.
	CheckAgents(context.Context, *v1.CheckAgentsRequest) (*v1.CheckAgentsResponse, error)
	// Projects.
	ListProjects(context.Context, *v1.ListProjectsRequest) (*v1.ListProjectsResponse, error)
	AddProject(context.Context, *v1.AddProjectRequest) (*v1.AddProjectResponse, error)
	RemoveProject(context.Context, *v1.RemoveProjectRequest) (*v1.RemoveProjectResponse, error)
	// Agents.
	ListClients(context.Context, *v1.ListClientsRequest) (*v1.ListClientsResponse, error)
	UpdateClient(context.Context, *v1.UpdateClientRequest) (*v1.UpdateClientResponse, error)
	RevokeClient(context.Context, *v1.RevokeClientRequest) (*v1.RevokeClientResponse, error)
	// Sessions (read across all reachable machines over E2E).
	ListSessions(context.Context, *v1.ListSessionsRequest) (*v1.ListSessionsResponse, error)
	// WatchSessions pushes session changes from every reachable machine as
	// they happen (hermeshd keeps one SessionService.WatchSessions stream per
	// online machine while anyone watches). A watcher that falls behind is
	// ended (RESOURCE_EXHAUSTED) and should watch again.
	WatchSessions(context.Context, *v1.WatchSessionsRequest, *connect.ServerStream[v1.WatchSessionsResponse]) error
	StreamSessionEvents(context.Context, *v1.StreamSessionEventsRequest, *connect.ServerStream[v11.SessionEvent]) error
	InterruptSession(context.Context, *v1.InterruptSessionRequest) (*v1.SessionResponse, error)
	ArchiveSession(context.Context, *v1.ArchiveSessionRequest) (*v1.SessionResponse, error)
	UnarchiveSession(context.Context, *v1.UnarchiveSessionRequest) (*v1.SessionResponse, error)
	AnswerQuestion(context.Context, *v1.AnswerQuestionRequest) (*v1.AnswerQuestionResponse, error)
	GetDiff(context.Context, *v1.GetDiffRequest) (*v11.GetDiffResponse, error)
	// GetUsage adds up every reachable machine's tokens by day and coding
	// agent (hermesh.session.v1.SessionService.GetUsage).
	GetUsage(context.Context, *v1.GetUsageRequest) (*v1.GetUsageResponse, error)
	// Notifications while the app is not running (the iPhone): this device's
	// push token and notice key, signed with its device key and sent to the
	// relay, which hands them to the owner's machines.
	RegisterPush(context.Context, *v1.RegisterPushRequest) (*v1.RegisterPushResponse, error)
}

